import json
import requests
from ..exceptions import ClientConnectionFailed
try:
    from urllib.parse import urljoin
except ImportError:
    from urlparse import urljoin  # python2


class Connection(object):

    URL_PREFIX = 'http://'
    SERVER_URL = '{ip}:{port}'

    def __init__(self, server_ip, server_port=8080):
        self.server_ip = server_ip
        self.server_port = server_port

        if server_ip.startswith('https'):
            raise ClientConnectionFailed('`https` connection not supported. Use `http`.')
        elif server_ip.startswith('http'):
            self.server_url = self.SERVER_URL.format(ip=server_ip, port=server_port)
        else:
            self.server_url = self.URL_PREFIX + self.SERVER_URL.format(ip=server_ip, port=server_port)

    def get(self, endpoint):
        location_url = urljoin(self.server_url, endpoint)
        try:
            response = requests.get(url=location_url)
        except requests.exceptions.RequestException as rq_e:
            raise ClientConnectionFailed("Client connection to endpoint failed with error {}".format(rq_e))
        response.raise_for_status()
        return response

    def post(self, endpoint, data, **kwargs):
        location_url = urljoin(self.server_url, endpoint)
        data = json.dumps(data)
        try:
            response = requests.post(url=location_url, data=data, **kwargs)
        except requests.exceptions.RequestException as rq_e:
            raise ClientConnectionFailed("Client connection to endpoint failed with error {}".format(rq_e))
        response.raise_for_status()
        return response
